#nullable enable // autogenerated

using Cysharp.Threading.Tasks;
using MVZ2.Managers;
using UnityEngine;

namespace MVZ2.ResourcePacks
{
    public abstract class ResourcePackReader : IResourcePackReader
    {
        protected ResourcePackReader(MainManager main)
        {
            Main = main;
        }
        protected string GetLanguagePackSpriteCategory(string key)
        {
            return Main.ResourcePackManager.GetResourcePackSpriteCategory(key);
        }
        protected Texture2D? ReadTexture2D(ResourceLoader loader, string path, string name)
        {
            var bytes = loader.LoadBytes(path);
            if (bytes == null)
                return null;
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
        public abstract UniTask<ResourcePack?> ReadPack(ResourceLoader loader, string key);
        public MainManager Main { get; private set; }
    }
}
